solution.code:
#include <stdio.h>

int power(int base, int exp) {
    if (exp == 0) {
        return 1;
    }
    int half = power(base, exp / 2);
    if (exp % 2 == 0) {
        return half * half;
    }
    return half * half * base;
}

int main() {
    printf("%d\n", power(2, 10));
    return 0;
}
